    "label": "Уся центральна апаратна заживлена через онлайнові джерела безперебійного живлення (Online ",
    "uk": "Уся центральна апаратна заживлена через онлайнові джерела безперебійного живлення (Online UPS). Повний імунітет до стрибків напруги, перешкод та вимкнень електрики.",
    "ru": "Вся центральная аппаратная запитана через онлайновые источники бесперебойного питания (Online UPS). Полный иммунитет к скачкам напряжения, помехам и отключениям электричества.",
    "en": "The entire central production system runs through online double-conversion UPS units, protecting the broadcast from voltage spikes, interference and power outages."
